function chapterTitle(c){return state.mode==='ja'?(japaneseNames[`chapter-${c.id}`]||text(c.titleZh,c.titleEn)):text(c.titleZh,c.titleEn);}
function lessonTitle(l){return state.mode==='ja'?(japaneseNames[l.id]||text(l.titleZh,l.titleEn)):text(l.titleZh,l.titleEn);}
function conceptTitle(c){return state.mode==='ja'?(japaneseNames[c.id]||text(c.titleZh,c.titleEn)):text(c.titleZh,c.titleEn);}
