function stationStatus(c,path){
 const values=[];
 if(c.complete)values.push(text('已完成','Completed','読了'));
 if(c.id===path.last?.chapter)values.push(text('目前位置','Current','現在地'));
 if(c.id===path.next?.chapter)values.push(text('下一站','Next stop','次の駅'));
 return values.join(' · ');
}
function connectedRoute(path,compact=false){
 const layout=routeGeometry(path.stages,compact);
 const arrows=layout.edges.map(edge=>{const a=layout.nodes.find(n=>n.chapter.id===edge.from),b=layout.nodes.find(n=>n.chapter.id===edge.to);let x=(a.x+b.x)/2,y=(a.y+b.y)/2,angle=compact?90:b.row===a.row?(b.x>a.x?0:180):90;if(!compact&&a.row!==b.row)x=a.x+(a.row%2?-45:45);return `<path class="route-direction ${edge.complete?'edge-done':''}" d="M-4 -4 L2 0 L-4 4" transform="translate(${x} ${y}) rotate(${angle})"/>`;}).join('');
 return `<svg class="connected-map ${compact?'compact-route':'wide-route'}" viewBox="0 0 ${layout.width} ${layout.height}" role="group" aria-label="${text('21 章串連學習路線圖','Connected route through all 21 chapters','全20章を結ぶ学習ルート')}"><g aria-hidden="true">${layout.edges.map(edge=>`<path class="route-connection ${edge.complete?'edge-done':''}" data-edge-from="${edge.from}" data-edge-to="${edge.to}" d="${edge.d}"/>`).join('')}${arrows}${path.stages.map((stage,i)=>{const first=layout.nodes.find(n=>n.stage===stage);return `<text class="map-stage-label" x="${compact?20:18}" y="${first.y-(compact?43:55)}">${text('階段','Stage','段階')} ${i+1} · ${esc(text(...stage.title))}</text>`;}).join('')}</g>${layout.nodes.map(node=>{
 const c=node.chapter,current=c.id===path.last?.chapter,next=c.id===path.next?.chapter,status=stationStatus(c,path),lines=wrapMapLabel(chapterTitle(c),compact?16:(state.mode==='en'?18:12)),tx=compact?83:node.x,ty=compact?node.y+5:node.y+61;
 return `<a class="route-node ${c.complete?'node-done':''} ${current?'node-current':''} ${next?'node-next':''}" href="${lessonHref(c.nextId)}" data-map-node="${c.id}" ${current?'aria-current="step"':''} aria-label="${esc(`${chapterLabel(c.id)} ${chapterTitle(c)} ${status} ${c.readCount}/${c.sectionIds.length}`)}"><title>${esc(`${chapterLabel(c.id)} · ${chapterTitle(c)} · ${status}`)}</title><circle class="node-hit-area" cx="${node.x}" cy="${node.y}" r="34"/><circle class="node-current-ring" cx="${node.x}" cy="${node.y}" r="30"/><circle class="node-disc" cx="${node.x}" cy="${node.y}" r="22"/><text class="node-number" x="${node.x}" y="${node.y+5}" text-anchor="middle">${c.complete?'✓':String(c.id).padStart(2,'0')}</text>${next?`<path class="node-next-pin" d="M${node.x-5} ${node.y-38}h10l-5 7z"/>`:''}<text class="map-chapter-label" x="${tx}" y="${compact?node.y-17:node.y+43}" text-anchor="${compact?'start':'middle'}">${chapterLabel(c.id)} · ${c.readCount}/${c.sectionIds.length}</text><text class="map-node-title" x="${tx}" y="${ty}" text-anchor="${compact?'start':'middle'}">${lines.map((line,i)=>`<tspan x="${tx}" dy="${i?18:0}">${esc(line)}</tspan>`).join('')}</text><text class="map-node-status" x="${tx}" y="${ty+lines.length*18+5}" text-anchor="${compact?'start':'middle'}">${wrapMapLabel(status,compact?30:state.mode==='en'?22:14).map((line,i)=>`<tspan x="${tx}" dy="${i?14:0}">${esc(line)}</tspan>`).join('')}</text></a>`;
 }).join('')}</svg>`;
}
function learningMap(){
 const path=buildLearningPath(data.chapters,data.lessons,state.read,state.lastLesson),completed=path.stages.flatMap(s=>s.items).filter(c=>c.complete).length;
 return `<div class="page transit-page"><header class="transit-heading"><p class="eyebrow">THE DATA SCIENCE ROUTE MAP</p><h1>${text('每一章，都是一個前進的節點。','Every chapter is a stop on your journey.','一つひとつの章が、学びの駅になる。')}</h1><p>${text('沿著連線依原書順序前進，也能點選任何節點自由探索。完成以「全章小節已讀」判定。雙環記錄上次開啟的章節，小旗依原書順序指出第一個未讀小節；測驗成績另計。','Follow the connections in book order, or select any station. A chapter is complete when all its sections are read. The double ring marks your last-opened chapter; the pennant points to the first unread section in book order. Quiz scores are separate.','線に沿って原書の順に進んでも、好きな駅を選んでもかまいません。全節の既読で章の読了を判定します。二重の輪は前回開いた章、小旗は原書の順で最初の未読の節を示します。問題の成績は別に記録します。')}</p></header><section class="route-status-strip" aria-label="${text('路線狀態','Route status','ルートの状態')}"><div><span class="status-key done-key">${text('已完成','Completed','読了')}</span><strong>${completed} / ${data.chapters.length} ${text('章','chapters','章')}</strong><small>${path.readCount} / ${data.lessons.length} ${text('小節已讀','sections read','節が既読')}</small></div><div><span class="status-key current-key">${text('目前位置','Current position','現在地')}</span><strong>${path.last?chapterLabel(path.last.chapter):text('尚未開始','Not started','未開始')}</strong><small>${path.last?esc(lessonTitle(path.last)):text('開啟一節，留下閱讀位置','Open a section to set your position','節を開くと現在地が記録されます')}</small></div><div><span class="status-key next-key">${text('下一站','Next stop','次の駅')}</span><strong>${path.next?chapterLabel(path.next.chapter):text('全書已讀完','Route complete','全章読了')}</strong><small>${path.next?esc(lessonTitle(path.next)):text('可以回到練習複習','Return to practice for review','問題で復習しましょう')}</small></div></section><div class="route-map-toolbar"><p>${text('實心打勾＝已完成　雙環＝目前位置　小旗＝下一站','Filled check = completed · Double ring = current · Pennant = next','チェック入り＝読了　　二重の輪＝現在地　　小旗＝次の駅')}</p><a class="primary-button" href="${path.next?lessonHref(path.next.id):'#/progress'}">${path.next?text('前往下一個未讀小節','Go to the next unread section','次の未読の節へ'):text('查看學習紀錄','View learning record','学習記録を見る')}</a></div><div class="map-locate-controls"><button class="secondary-button" data-locate-node="${path.last?.chapter||''}" ${path.last?'':'disabled'}>${text('定位目前位置','Locate current station','現在地を表示')}</button><button class="secondary-button" data-locate-node="${path.next?.chapter||''}" ${path.next?'':'disabled'}>${text('定位下一站','Locate next station','次の駅を表示')}</button></div><div class="transit-canvas">${connectedRoute(path)}${connectedRoute(path,true)}</div><div class="route-stage-goals">${path.stages.map((stage,i)=>`<details><summary>${text('階段','Stage','段階')} ${i+1} · ${esc(text(...stage.title))}<span>${stage.readCount}/${stage.total}</span></summary><p>${esc(text(...stage.goal))}</p><p><strong>${text('目標：','Goal: ','目標：')}</strong>${esc(text(...stage.milestone))}</p></details>`).join('')}</div><p class="map-source-link">Learning Data Science · Lau, Gonzalez & Nolan · <a href="#/">${text('原書、作者與資料出處','Book, author and sources','原書・著者・出典')}</a></p></div>`;
}

