function markdownHtml(md){
 const maths=[];
 const protectedMd=String(md).replace(/```[\s\S]*?```|\$\$[\s\S]*?\$\$|\$[^\n$]+?\$/g,raw=>{
  if(raw.startsWith('```'))return raw;
  const display=raw.startsWith('$$'),tex=raw.slice(display?2:1,display?-2:-1);
  if(/^\d[\d, .]*$/.test(tex)||(!display&&/[\u3040-\u30ff\u3400-\u9fff]/u.test(tex)&&!tex.includes('\\text')))return raw;
  const n=maths.length;maths.push({tex,display});return `MATHPLACEHOLDER${n}END`;
 });
 let html=DOMPurify.sanitize(marked.parse(protectedMd,{gfm:true,breaks:false}));
 html=html.replace(/MATHPLACEHOLDER(\d+)END/g,(_,i)=>{const m=maths[+i];return katex.renderToString(m.tex,{displayMode:m.display,throwOnError:false,strict:false,trust:false,output:'htmlAndMathml'});});
 return html;
}
function literalBody(l){
 return `<div class="translation-context"><span class="translation-label">${text('本站獨立導讀 · 非原書逐段譯文','INDEPENDENT GUIDE · NOT A BOOK TRANSLATION')}</span><span>${t('printPage')} ${l.printPage}–${l.printEnd}</span></div>${l.blocks.map((b,i)=>`<section class="content-block" data-block-id="${b.id}"><h2>${t(i?'explanation':'intuition')}</h2>${bilingual(b)}</section>`).join('')}<section class="example-card" data-block-id="example"><h3>${t('example')}</h3>${bilingual(l.example)}</section><section class="code-section content-block" data-block-id="code"><div class="section-heading"><h2>${text('動手做：可重現的小實驗','Try it: a reproducible experiment')}</h2><a class="text-button" href="./examples/chapter_${String(l.chapter).padStart(2,'0')}.py" download>${text('下載 Python','Download Python')}</a></div><p class="small muted">${text('本站自編範例，使用合成資料。此頁展示程式碼；請在自己的 Python 環境執行。','Original example with synthetic data. Code is displayed here; run it in your own Python environment.')}</p><pre class="python-code"><code>${esc(l.code)}</code></pre><details><summary>${text('執行環境','Environment')}</summary><pre><code>python -m pip install numpy pandas matplotlib scikit-learn
python examples/chapter_${String(l.chapter).padStart(2,'0')}.py</code></pre></details></section><details class="source-outline content-block" data-block-id="outline"><summary>${text('原書本章小節與頁碼','Source chapter outline and pages')} · ${l.sourceSections.length}</summary><p class="small muted">${text('以下為原書目錄索引；本頁是一篇章節概念導讀，未逐段翻譯每個小節。點頁碼可定位你自行選取的 PDF。','This is the source outline. This page is a chapter overview, not a translation of every subsection. Page buttons locate your locally selected PDF.')}</p>${l.sourceSections.map(s=>`<div class="source-outline-row" style="padding-left:${(s.level-1)*16}px"><span lang="en">${esc(s.title)}</span><button class="text-button" data-source-page="${s.pdfPage}" aria-label="${esc(s.title)}, ${t('printPage')} ${s.printPage}">p. ${s.printPage}</button></div>`).join('')}</details>`;
}

