function quizCard(l,q,index){const key=`${l.id}::${q.id}`,a=state.attempts[key];const checked=a?.checked,chosen=a?.choice;return `<form class="quiz-card" data-quiz="${esc(q.id)}" data-block-id="quiz-${esc(q.id)}"><div class="block-kicker">${text('理解檢查','CONCEPT CHECK')} ${index+1}</div><div class="quiz-question">${esc(text(q.question.zh,q.question.en))}${state.mode==='both'?`<div class="muted small" lang="en">${esc(q.question.en)}</div>`:''}</div><div class="quiz-options" role="radiogroup" aria-label="${esc(text(q.question.zh,q.question.en))}">${q.options.map((o,i)=>`<label class="quiz-option ${checked&&o.id===q.correct?'correct':checked&&o.id===chosen&&chosen!==q.correct?'incorrect':''}"><input type="radio" name="answer-${esc(q.id)}" value="${esc(o.id)}" ${o.id===chosen?'checked':''}><span class="option-letter">${String.fromCharCode(65+i)}</span><span>${esc(text(o.zh,o.en))}${state.mode==='both'?`<span class="muted small" lang="en" style="display:block">${esc(o.en)}</span>`:''}</span></label>`).join('')}</div>${checked?`<div class="quiz-feedback ${a.correct?'':'try-again'}" role="status"><strong>${a.correct?t('correct'):t('incorrect')}</strong><br>${esc(text(q.explanation.zh,q.explanation.en))}${state.mode==='both'?`<br><span lang="en">${esc(q.explanation.en)}</span>`:''}</div>`:''}<div class="quiz-actions"><button class="primary-button" type="submit">${t('check')}</button><button class="text-button" type="button" data-retry="${esc(q.id)}">${t('retry')}</button></div></form>`;}
