function lesson(l){
 const chapter=data.chapters.find(c=>c.id===l.chapter),idx=data.lessons.indexOf(l),prev=data.lessons[idx-1],next=data.lessons[idx+1],v=visualForLesson(l.id);
 return `<div class="page reading-page"><div class="breadcrumbs"><a href="#/map">${t('map')}</a><span>/</span><span>${chapterLabel(l.chapter)}</span></div><div class="lesson-layout"><article class="lesson-article"><header class="lesson-header"><div class="eyebrow">${chapterLabel(l.chapter)} · ${esc(chapterTitle(chapter))}</div><h1>${esc(lessonTitle(l))}</h1><p class="original-title">${esc(state.mode==='en'?l.titleZh:l.titleEn)}</p><div class="lesson-meta"><span class="pill">${t('guide')}</span><span>${t('printPage')} ${l.printPage}–${l.printEnd} · PDF ${l.pdfPage}–${l.pdfEnd}</span><span id="lesson-read-label">${state.read.includes(l.id)?'✓ '+t('completed'):''}</span></div></header><nav class="lesson-tabs"><a href="#literal-content" data-scroll="literal-content">${t('guide')}</a><a href="#source-panel" data-scroll="source-panel" id="source-tab" aria-expanded="${state.sourceOpen}">${t('source')}</a><a href="#quiz-section" data-scroll="quiz-section">${t('quiz')}</a></nav>${v?renderVisual(v.id,state.mode):''}${literalSection(l)}${sourcePanel(l,currentSourceLoaded)}<section class="quiz-section content-block" id="quiz-section" data-block-id="quiz"><p class="eyebrow">CHECK YOUR UNDERSTANDING</p><h2>${text('讀完之後，試著想一想。','Pause for a concept check.')}</h2><p class="quiz-intro">${t('quizIntro')}</p>${l.quiz.map((q,i)=>quizCard(l,q,i)).join('')}<p class="quiz-note">${t('quizNote')}</p></section><div class="completion-area content-block" data-block-id="completion"><p>${t('completionNote')}</p><button id="mark-read" class="primary-button" aria-pressed="${state.read.includes(l.id)}">${icon('check')}${state.read.includes(l.id)?t('completed'):t('complete')}</button></div><div class="lesson-navigation">${prev?`<a href="${lessonHref(prev.id)}"><small>${t('previous')}</small>${esc(lessonTitle(prev))}</a>`:'<span></span>'}${next?`<a href="${lessonHref(next.id)}"><small>${t('next')}</small>${esc(lessonTitle(next))}</a>`:`<a href="#/progress">${t('progress')}</a>`}</div><p class="content-status">${text('本站導讀與自編練習獨立於原書。原書每章頁碼已核對提供的 597 頁第一版 PDF；印刷頁碼 + 22 = PDF 頁碼。','Independent guides and original checks are separate from the source. Chapter ranges were mapped to the supplied 597-page first-edition PDF; printed page + 22 = PDF page.')}</p></article><aside class="lesson-rail"><div class="rail-title">${text('閱讀控制','READING CONTROLS')}</div><nav class="rail-list"><a href="#literal-content" data-scroll="literal-content">${t('guide')}</a><a href="#source-panel" data-scroll="source-panel">${t('source')}</a><a href="#quiz-section" data-scroll="quiz-section">${t('quiz')}</a></nav><div class="rail-source">LEARNING DATA SCIENCE<br>Lau · Gonzalez · Nolan<br>${t('printPage')} ${l.printPage}–${l.printEnd}<a href="https://learningds.org/" target="_blank" rel="noopener">${text('作者線上教材','Authors’ online material')}</a></div></aside></div></div>`;
}

