function bindLesson(){
 const l=currentLesson;
 document.querySelectorAll('[data-scroll]').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();if(a.dataset.scroll==='source-panel'){const opening=!state.sourceOpen;toggleSource(opening);if(opening)$('#source-panel').scrollIntoView({behavior:'smooth'});}else document.getElementById(a.dataset.scroll)?.scrollIntoView({behavior:'smooth'});}));
 document.querySelectorAll('[data-source-page]').forEach(b=>b.addEventListener('click',()=>{pdfPageNumber=Number(b.dataset.sourcePage);toggleSource(true);updatePdfControls();$('#source-panel').scrollIntoView({behavior:'smooth'});}));
 $('#mark-read').addEventListener('click',()=>{if(!state.read.includes(l.id))state.read.push(l.id);save();sidebar();$('#mark-read').innerHTML=icon('check')+t('completed');$('#mark-read').setAttribute('aria-pressed','true');$('#lesson-read-label').textContent='✓ '+t('completed');toast(t('saved'));});
 bindQuizzes();bindSource();
}

function bindQuizzes(){document.querySelectorAll('form[data-quiz]').forEach(form=>{const q=currentLesson.quiz.find(q=>q.id===form.dataset.quiz),key=`${currentLesson.id}::${q.id}`;form.addEventListener('change',e=>{if(e.target.name?.startsWith('answer-')){const prev=state.attempts[key]||{};state.attempts[key]={...prev,choice:e.target.value,checked:false};save();if(prev.checked)rerenderQuiz(q,form);}});form.addEventListener('submit',e=>{e.preventDefault();const selected=form.querySelector('input:checked');if(!selected){toast(t('selectFirst'));return;}const old=state.attempts[key]||{};state.attempts[key]={...old,choice:selected.value,checked:true,correct:selected.value===q.correct,attemptCount:(old.attemptCount||0)+1,updatedAt:new Date().toISOString()};save();rerenderQuiz(q,form);});form.querySelector('[data-retry]').addEventListener('click',()=>{const old=state.attempts[key]||{};state.attempts[key]={attemptCount:old.attemptCount||0,checked:false};save();rerenderQuiz(q,form);});});}
function rerenderQuiz(q,form){const wrapper=document.createElement('div');wrapper.innerHTML=quizCard(currentLesson,q,currentLesson.quiz.indexOf(q));form.replaceWith(wrapper.firstElementChild);/* Replace listeners only on the replaced form. */const newForm=document.querySelector(`form[data-quiz="${CSS.escape(q.id)}"]`);bindOneQuiz(newForm,q);}
function bindOneQuiz(form,q){const key=`${currentLesson.id}::${q.id}`;form.addEventListener('change',e=>{if(e.target.matches('input[type=radio]')){const old=state.attempts[key]||{};state.attempts[key]={...old,choice:e.target.value,checked:false};save();if(old.checked)rerenderQuiz(q,form);}});form.addEventListener('submit',e=>{e.preventDefault();const selected=form.querySelector('input:checked');if(!selected){toast(t('selectFirst'));return;}const old=state.attempts[key]||{};state.attempts[key]={...old,choice:selected.value,checked:true,correct:selected.value===q.correct,attemptCount:(old.attemptCount||0)+1,updatedAt:new Date().toISOString()};save();rerenderQuiz(q,form);});form.querySelector('[data-retry]').addEventListener('click',()=>{state.attempts[key]={attemptCount:state.attempts[key]?.attemptCount||0,checked:false};save();rerenderQuiz(q,form);});}

async function getPdf(){
 if(!localPdfBytes)throw new Error('Select a local PDF first');
 if(!pdfDocPromise)pdfDocPromise=(async()=>{const lib=await import('./vendor/pdf.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./vendor/pdf.worker.mjs',import.meta.url).href;return lib.getDocument({data:localPdfBytes.slice(),useSystemFonts:true}).promise;})().catch(e=>{pdfDocPromise=null;throw e;});
 return pdfDocPromise;
}

function bindSource(){
 $('#source-toggle')?.addEventListener('click',()=>toggleSource(!state.sourceOpen));
 $('#local-pdf')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>150_000_000){toast(text('請選擇小於 150 MB 的 PDF。','Choose a PDF smaller than 150 MB.'));return;}pdfVersion++;localPdfBytes=new Uint8Array(await file.arrayBuffer());localPdfName=file.name;pdfDocPromise=null;$('#pdf-file-name').textContent=localPdfName;try{const doc=await getPdf();if(doc.numPages!==597)toast(text('此檔案不是 597 頁，頁碼可能與課程索引不同。','This PDF has a different page count; course page mapping may differ.'));pdfPageNumber=Math.min(pdfPageNumber,doc.numPages);renderPdf();}catch{localPdfBytes=null;pdfDocPromise=null;toast(text('無法開啟此 PDF，請確認檔案有效且未加密。','Could not open the PDF. Check that it is valid and unencrypted.'));}});
 $('#pdf-prev')?.addEventListener('click',()=>goPdf(pdfPageNumber-1));$('#pdf-next')?.addEventListener('click',()=>goPdf(pdfPageNumber+1));
 $('#pdf-page-input')?.addEventListener('change',e=>{const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>575){updatePdfControls();return;}goPdf(n+22);});
 $('#enlarge-source')?.addEventListener('click',zoomSource);
 if(state.sourceOpen)loadSource();updatePdfControls();
}

function toggleSource(open){
 state.sourceOpen=!!open;save();
 const body=$('#source-body'),button=$('#source-toggle'),panel=$('#source-panel');
 if(body)body.hidden=!open;
 if(button){button.setAttribute('aria-expanded',String(!!open));button.textContent=open?text('✕ 關閉原文','✕ Close original'):text('展開原文','Open original');}
 panel?.classList.toggle('expanded',!!open);panel?.classList.toggle('collapsed',!open);
 $('#source-tab')?.setAttribute('aria-expanded',String(!!open));$('.parallel-columns')?.classList.toggle('source-is-collapsed',!open);
 if(open)loadSource();else{pdfVersion++;zoomRequest++;if(pdfRenderTask){pdfRenderTask.cancel();pdfRenderTask=null;}button?.focus({preventScroll:true});}
}
function loadSource(){if(!state.sourceOpen){toggleSource(true);return;}currentSourceLoaded=true;if(localPdfBytes)renderPdf();}

function goPdf(n){pdfPageNumber=Math.min(597,Math.max(23,n));updatePdfControls();if(localPdfBytes)renderPdf();}

async function zoomSource(){const ticket=++zoomRequest;const button=$('#enlarge-source');if(button)button.disabled=true;try{const doc=await getPdf(),n=pdfPageNumber,page=await doc.getPage(n),base=page.getViewport({scale:1}),viewport=page.getViewport({scale:1400/base.width}),canvas=document.createElement('canvas');canvas.width=Math.floor(viewport.width);canvas.height=Math.floor(viewport.height);await page.render({canvasContext:canvas.getContext('2d'),canvas,viewport}).promise;if(ticket!==zoomRequest||!state.sourceOpen)return;$('#large-image').src=canvas.toDataURL('image/png');$('#large-image').alt=text(`Learning Data Science 原書印刷頁 ${n-22}`,`Learning Data Science original book page ${n-22}`,`Learning Data Science 原書の書籍ページ ${n-22}`);$('#image-caption').textContent=`Learning Data Science · Lau, Gonzalez & Nolan · ${t('printPage')} ${n-22}`;$('#image-dialog').showModal();}catch{toast(text('無法放大，請先選取本機 PDF。','Could not enlarge this page. Select a local PDF first.'));}finally{if(button?.isConnected)button.disabled=false;}}
function updatePdfControls(){const input=$('#pdf-page-input');if(input)input.value=pdfPageNumber-22;const p=$('#pdf-prev'),n=$('#pdf-next');if(p)p.disabled=pdfPageNumber<=23;if(n)n.disabled=pdfPageNumber>=597;}

async function renderPdf(){const token=++pdfVersion,canvas=$('#pdf-canvas'),host=$('#pdf-canvas-host');if(!canvas||!host||!state.sourceOpen)return;const status=$('#pdf-status');status.textContent=t('loadingPdf');try{const doc=await getPdf();if(token!==pdfVersion||!canvas.isConnected)return;if(pdfRenderTask){pdfRenderTask.cancel();try{await pdfRenderTask.promise;}catch{}pdfRenderTask=null;}const page=await doc.getPage(pdfPageNumber);if(token!==pdfVersion||!canvas.isConnected)return;const base=page.getViewport({scale:1}),width=Math.max(220,Math.min(host.clientWidth-24,1000)),scale=width/base.width,ratio=Math.min(window.devicePixelRatio||1,2),viewport=page.getViewport({scale});canvas.width=Math.floor(viewport.width*ratio);canvas.height=Math.floor(viewport.height*ratio);canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';canvas.setAttribute('aria-label',text(`Learning Data Science 原書印刷頁 ${pdfPageNumber-22}。下方可展開輔助文字。`,`Learning Data Science original page ${pdfPageNumber-22}. Extracted reference text is available below.`,`Learning Data Science 原書の書籍ページ ${pdfPageNumber-22}。下に補助テキストがあります。`));pdfRenderTask=page.render({canvasContext:canvas.getContext('2d'),canvas,viewport,transform:ratio!==1?[ratio,0,0,ratio,0,0]:null});await pdfRenderTask.promise;if(token===pdfVersion)status.textContent=`Learning Data Science · ${t('printPage')} ${pdfPageNumber-22} · ${t('pdfPage')} ${pdfPageNumber} / 597`;}catch(e){if(e?.name==='RenderingCancelledException')return;if(token===pdfVersion&&status.isConnected){status.innerHTML=`${text('原書暫時無法顯示，請使用「開啟原書 PDF」。','Unable to render the page. Use “Open original PDF” instead.')} <button class="text-button" id="retry-pdf">${text('重試','Retry')}</button>`;$('#retry-pdf')?.addEventListener('click',renderPdf);}console.error('PDF rendering failed:',e);}}

async function changeLanguage(mode){if(state.mode===mode)return;if(mode==='ja'){try{document.querySelectorAll('[data-mode]').forEach(b=>b.disabled=true);await loadJapaneseLocale();}catch{toast('日本語の教材を読み込めません。もう一度お試しください。');return;}finally{document.querySelectorAll('[data-mode]').forEach(b=>b.disabled=false);}}const blocks=[...document.querySelectorAll('[data-block-id]')];const anchor=blocks.filter(e=>e.getBoundingClientRect().top<=150).at(-1)||blocks.find(e=>e.getBoundingClientRect().top>=0);const anchorId=anchor?.dataset.blockId,offset=anchor?.getBoundingClientRect().top,oldY=scrollY;state.mode=mode;save();render({preserveScroll:true,preserveSource:true});requestAnimationFrame(()=>{const target=anchorId?document.querySelector(`[data-block-id="${CSS.escape(anchorId)}"]`):null;if(target&&Number.isFinite(offset))window.scrollTo(0,scrollY+target.getBoundingClientRect().top-offset);else window.scrollTo(0,oldY);});}
function glossary(){return `<div class="page"><div class="page-heading"><p class="eyebrow">A SHARED LANGUAGE</p><h1>${t('glossary')}</h1><p>${text('把重要名詞放在同一個地方，隨時回來找。','A shared reference for the ideas you meet across chapters.')}</p></div><input id="glossary-search" class="glossary-search" type="search" placeholder="${text('搜尋中文或英文名詞…','Search a Chinese or English term…')}" aria-label="${text('搜尋概念','Search concepts')}"><div id="glossary-results" class="glossary-grid">${glossaryCards('')}</div></div>`;}
function glossaryCards(query){const items=data.concepts.filter(c=>`${c.titleZh} ${c.titleEn} ${conceptTitle(c)} ${c.definitionZh} ${c.definitionEn} ${text(c.definitionZh,c.definitionEn)}`.toLowerCase().includes(query.toLowerCase()));return items.map(c=>`<article class="glossary-card"><div class="term-title"><h3>${esc(conceptTitle(c))}</h3><span class="pill">${chapterLabel(c.chapter)}</span></div><div class="term-english">${esc(state.mode==='ja'?c.titleEn:text(c.titleEn,c.titleZh))}</div><p>${esc(text(c.definitionZh,c.definitionEn))}</p><a href="${lessonHref(c.lessonId)}">${text('回到概念導讀','Read the concept guide')}</a></article>`).join('')||`<p class="muted">${t('noMatches')}</p>`;}
function validAttempts(){return Object.entries(state.attempts).filter(([key,a])=>{const [id,q]=key.split('::');return data.lessonsById[id]?.quiz.some(x=>x.id===q)&&a?.checked;});}
function progress(){const attempts=validAttempts(),read=state.read.filter(id=>data.lessonsById[id]);return `<div class="page"><div class="page-heading"><p class="eyebrow">YOUR OWN PACE</p><h1>${text('每一點理解，都有留下來。','Every small understanding counts.')}</h1><p>${text('這是你在本機瀏覽器的學習紀錄；已讀與練習表現分開計算。','Your learning record in this browser. Reading and quiz results are counted separately.')}</p></div>${!storageAvailable?`<div class="storage-warning">${text('此瀏覽器無法持久保存資料，請匯出備份。','Persistent storage is unavailable. Please export a backup.')}</div>`:''}<div class="progress-cards"><div class="progress-stat"><strong>${read.length}</strong><span>${text('小節已讀','sections read')} / ${data.lessons.length}</span></div><div class="progress-stat"><strong>${attempts.length}</strong><span>${text('概念題已檢查','questions checked')}</span></div><div class="progress-stat"><strong>${attempts.filter(([,a])=>a.correct).length}</strong><span>${text('目前答對','currently correct')}</span></div></div><div class="button-row"><button id="export-progress" class="secondary-button">${icon('download')}${text('匯出進度','Export progress')}</button><label class="secondary-button" for="import-progress">${text('匯入進度','Import progress')}</label><input id="import-progress" type="file" accept="application/json,.json" hidden></div><div class="section-heading"><h2>${text('最近的練習','Recent practice')}</h2></div>${attempts.length?attempts.sort((a,b)=>String(b[1].updatedAt).localeCompare(String(a[1].updatedAt))).slice(0,30).map(([key,a])=>{const [id]=key.split('::'),l=data.lessonsById[id];return `<div class="attempt-row"><span class="muted small">${chapterLabel(l.chapter)}</span><a href="${lessonHref(id)}">${esc(lessonTitle(l))}</a><span class="result ${a.correct?'':'retry'}">${a.correct?text('已理解','Correct'):text('再練一下','Try again')}</span></div>`;}).join(''):`<div class="empty-state"><h3>${text('從一個小問題開始。','Begin with one small question.')}</h3><p>${text('先讀一節導讀，再試著作答。這裡就會留下你的學習足跡。','Read a concept guide and try its check. Your results will appear here.')}</p><a class="primary-button" href="${lessonHref(data.lessons[0].id)}">${t('start')}</a></div>`}<div class="section-heading"><h2>${text('各章閱讀進度','Reading by chapter')}</h2></div><div class="chapters-grid">${data.chapters.map(chapterCard).join('')}</div></div>`;}
function bindProgress(){ $('#export-progress').addEventListener('click',()=>{const blob=new Blob([JSON.stringify({format:'learning-data-science-progress',version:1,exportedAt:new Date().toISOString(),state},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='learning-data-science-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});$('#import-progress').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('too large');const backup=JSON.parse(await file.text());if(backup.format!=='learning-data-science-progress'||backup.version!==1||!backup.state||!Array.isArray(backup.state.read)||!backup.state.attempts||Array.isArray(backup.state.attempts)||typeof backup.state.attempts!=='object')throw new Error('invalid');const s=backup.state;state.read=[...new Set([...state.read,...s.read.filter(id=>typeof id==='string'&&data.lessonsById[id])])];for(const [key,a] of Object.entries(s.attempts)){const [id,qid]=key.split('::');const q=data.lessonsById[id]?.quiz.find(q=>q.id===qid);if(!q||!a||typeof a!=='object')continue;const choice=q.options.some(o=>o.id===a.choice)?a.choice:undefined;if(!choice)continue;const old=state.attempts[key];const date=typeof a.updatedAt==='string'&&!Number.isNaN(Date.parse(a.updatedAt))?a.updatedAt:'1970-01-01T00:00:00Z';if(old?.updatedAt&&old.updatedAt>date)continue;state.attempts[key]={choice,checked:!!a.checked,correct:choice===q.correct,attemptCount:Number.isSafeInteger(a.attemptCount)&&a.attemptCount>=0?a.attemptCount:0,updatedAt:date};}save();render({preserveScroll:true});toast(text('進度已合併匯入。','Progress imported and merged.'));}catch{toast(text('無法讀取這份進度檔，請選擇本站匯出的 JSON。','Could not read this file. Choose a progress JSON exported from this site.'));}});}
function about(){const d=$('#about-dialog');d.innerHTML=`<div class="dialog-top"><h2>${t('attribution')}</h2><button class="icon-button" id="close-about" aria-label="${text('關閉','Close')}">×</button></div><h3>Learning Data Science</h3><p>Sam Lau · Joseph Gonzalez · Deborah Nolan<br>First edition · 2023 · O’Reilly Media<br>ISBN 9781098113001</p><p>${text('這是獨立製作的學習伴讀，並非作者或出版社官方網站，也不代表其背書。原書著作權另計，不隨網站公開散布。本站提供 21 篇自行撰寫的中英導讀、42 題概念檢查與合成資料範例；不宣稱是原書全文翻譯。','This is an independent learning companion, not an official or endorsed publication. The source book retains its own copyright and is not distributed here. The site offers 21 independently authored bilingual guides, 42 checks, and synthetic-data examples, not a full book translation.')}</p><p><a href="https://learningds.org/" target="_blank" rel="noopener">${text('作者線上教材','Authors’ online material')}</a> · <a href="./coverage.json">${text('涵蓋清單','Coverage inventory')}</a></p><h3>${text('隱私與本機檔案','Privacy and local files')}</h3><p>${text('學習進度只存在本機瀏覽器。選取的 PDF 僅由 PDF.js 在瀏覽器中處理，不會上傳。無帳號、分析追蹤與測驗資料傳送；請匯出進度備份。','Progress stays in this browser. Selected PDFs are processed locally by PDF.js and are never uploaded. There are no accounts, analytics, or quiz-data uploads. Export progress for backup.')}</p><h3>${text('範本與軟體授權','Template and software licenses')}</h3><p>${text('網站沿用 Scientific Learning Site / Bayes Notes 的 MIT 程式與設計。保留其程式授權；本站新增導讀、程式範例及圖解採 CC BY 4.0。原書授權不受影響。','The site adapts the MIT-licensed Scientific Learning Site / Bayes Notes code and design. New guides, examples, and diagrams use CC BY 4.0. The book’s copyright is separate.')}</p><p><a href="./CONTENT-LICENSE.txt">${text('教材授權','Content license')}</a> · <a href="./LICENSE">MIT</a> · <a href="./vendor/PDFJS-LICENSE.txt">PDF.js</a></p>`;$('#close-about').addEventListener('click',()=>d.close());d.showModal();}

function render(options={}){
 $('#close-image').textContent=text('✕ 關閉原文','✕ Close original','✕ 原文を閉じる');$('#close-image').setAttribute('aria-label',text('關閉原文','Close original','原文を閉じる'));
 $('#sidebar').setAttribute('aria-label',text('課程目錄','Course contents','目次'));$('.skip-link').textContent=text('跳到主要內容','Skip to content','本文へ移動');
 pdfVersion++;if(pdfRenderTask){pdfRenderTask.cancel();pdfRenderTask=null;}
 document.documentElement.lang=state.mode==='en'?'en':state.mode==='ja'?'ja':'zh-Hant';
 if(!options.preserveSource){currentSourceLoaded=false;pdfPageNumber=currentLesson?.pdfPage||25;}
 const wasMenuOpen=$('#sidebar').classList.contains('open');sidebar();if(wasMenuOpen)$('#sidebar').classList.add('open');topbar();footer();
 if(route.name==='lesson'){state.lastLesson=currentLesson.id;save();$('#main').innerHTML=lesson(currentLesson);document.title=`${lessonTitle(currentLesson)} · ${text('資料科學慢學','Data Science Notes')}`;bindLesson();}
 else if(route.name==='home'||route.name==='map'||route.name==='chapters'){$('#main').innerHTML=route.name==='home'?landingPage():learningMap();if(route.name!=='home')bindConnectedMap();document.title=`${text('資料科學慢學','Data Science Notes')} · Data, step by step`;}
 else if(route.name==='visuals'){$('#main').innerHTML=visualGallery(state.mode);document.title=`${t('visuals')} · Data Science Notes`;}
 else if(route.name==='glossary'){$('#main').innerHTML=glossary();$('#glossary-search').addEventListener('input',e=>$('#glossary-results').innerHTML=glossaryCards(e.target.value));document.title=`${t('glossary')} · Data Science Notes`;}
 else if(route.name==='progress'){$('#main').innerHTML=progress();bindProgress();document.title=`${t('progress')} · Data Science Notes`;}
 else{$('#main').innerHTML=`<div class="page"><div class="empty-state"><h1>${text('找不到這一節','Section not found')}</h1><p>${text('這個連結可能已改變，請從學習地圖繼續。','This link may have changed. Continue from the learning map.')}</p><a class="primary-button" href="#/chapters">${t('home')}</a></div></div>`;}
 bindVisualGuides();
 if(!options.preserveScroll)window.scrollTo(0,0);
}

$('#close-image').addEventListener('click',()=>{zoomRequest++;$('#image-dialog').close();});
$('#concept-dialog').addEventListener('click',e=>{if(e.target===$('#concept-dialog'))$('#concept-dialog').close();});
$('#image-dialog').addEventListener('click',e=>{if(e.target===$('#image-dialog')){zoomRequest++;$('#image-dialog').close();}});
document.addEventListener('click',e=>{if(document.body.classList.contains('menu-open')&&!e.target.closest('#sidebar')&&!e.target.closest('#menu-toggle')){document.body.classList.remove('menu-open');$('#sidebar').classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false');}});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){$('#main').focus();return;}document.body.classList.remove('menu-open');$('#sidebar').classList.remove('open');navigate();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#image-dialog').open&&!$('#about-dialog').open&&!$('#concept-dialog').open&&state.sourceOpen)toggleSource(false);document.body.classList.remove('menu-open');$('#sidebar').classList.remove('open');$('#menu-toggle')?.setAttribute('aria-expanded','false');}});

try{
 const response=await fetch(new URL('./content.json',import.meta.url),{cache:'no-cache'});if(!response.ok)throw new Error(`Content HTTP ${response.status}`);data=await response.json();data.lessonsById=Object.fromEntries(data.lessons.map(l=>[l.id,l]));if(state.mode==='ja')await loadJapaneseLocale();parseRoute();render();
}catch(e){console.error('Learning site could not load:',e);$('#main').innerHTML='<div class="page"><h1>教材暫時無法載入 / Content unavailable</h1><p>請透過 HTTP 網址開啟網站並重新整理。 / Open this site over HTTP and reload.</p></div>';}
